<script setup lang="ts">
definePageMeta({layout:'admin'})
const {api,message,session}=useCmsAdmin(),editing=ref<any>(null),baseline=ref(''),resetting=ref<any>(null),password=ref(''),error=ref(''),notice=ref(''),busy=ref(false),q=ref('')
const {data:users,refresh,error:loadError}=await useAsyncData<any[]>('cms-users',()=>api('users'))
const filtered=computed(()=>(users.value||[]).filter(u=>`${u.name} ${u.email}`.includes(q.value)))
const dirty=computed(()=>!!editing.value&&JSON.stringify(editing.value)!==baseline.value)
useCmsUnsaved(dirty)
const lastAdmin=computed(()=>(users.value||[]).filter(u=>u.role==='admin'&&!u.disabled).length===1&&editing.value?.role==='admin'&&!editing.value?.disabled)
function open(user?:any){editing.value=user?{...user,password:''}:{email:'',name:'',role:'editor',disabled:false,password:''};baseline.value=JSON.stringify(editing.value);error.value=''}
function close(){if(!busy.value&&(JSON.stringify(editing.value)===baseline.value||window.confirm('帳號修改尚未儲存，確定關閉？')))editing.value=null}
async function save(body=editing.value){if(busy.value)return;busy.value=true;error.value='';try{await api('users'+(body.id?'/'+body.id:''),{method:'POST',body});if(body.id===session.value.id){await navigateTo('/admin/login');return}editing.value=null;resetting.value=null;password.value='';notice.value='帳號設定已儲存。';await refresh()}catch(e){error.value=message(e)}finally{busy.value=false}}
async function disable(){if(!window.confirm(editing.value.disabled?'重新啟用這個帳號？':'停用後，這個帳號會立即登出並無法使用後台，確定繼續？'))return;await save({...editing.value,disabled:!editing.value.disabled})}
</script>
<template><div class="cms-page"><div class="cms-heading"><h1>帳號</h1><button class="cms-button cms-button-gold" @click="open()">新增帳號</button></div><p v-if="loadError" class="cms-error" role="alert">{{ message(loadError) }}</p><p v-if="notice" class="cms-notice" role="status">{{ notice }}</p><label class="cms-search"><input v-model="q" aria-label="搜尋帳號" placeholder="搜尋姓名或電子郵件" /></label><div class="cms-panel"><button v-for="u in filtered" :key="u.id" class="cms-resource-row" @click="open(u)"><div><strong>{{ u.name }}</strong><small>{{ u.email }}</small></div><span>{{ u.role==='admin'?'管理員':'編輯者' }} · {{ u.disabled?'已停用':'使用中' }} →</span></button><p v-if="!filtered.length" class="cms-empty">沒有符合的帳號</p></div><AdminDialog :open="!!editing" :title="editing?.id?'修改帳號':'新增帳號'" @close="close"><form v-if="editing" class="cms-form" @submit.prevent="save()"><label>姓名<input v-model="editing.name" required maxlength="100" /></label><label>電子郵件<input v-model="editing.email" type="email" required maxlength="254" /></label><label>可以做的工作<select v-model="editing.role"><option value="editor">編輯者：修改內容、上傳圖片與預覽</option><option value="admin">管理員：另可更新官網、處理申請與管理帳號</option></select></label><p class="cms-field-help">編輯者看不到申請人的聯絡資料，也不能把修改更新到官網。</p><label v-if="!editing.id">第一次登入密碼<input v-model="editing.password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required /><small class="cms-field-help">至少 12 個字元；第一次登入後必須更換。</small></label><p v-if="error" class="cms-error" role="alert">{{ error }}</p><div class="cms-dialog-actions"><button v-if="editing.id" type="button" class="cms-button" :disabled="busy||dirty" @click="resetting={...editing};password='';error=''">重設密碼</button><button v-if="editing.id" type="button" class="cms-button" :disabled="busy||lastAdmin||dirty" @click="disable">{{ editing.disabled?'重新啟用':'停用帳號' }}</button><button class="cms-button cms-button-gold" :disabled="busy">{{ busy?'儲存中…':'儲存帳號' }}</button></div><p v-if="dirty&&editing.id" class="cms-field-help">先儲存姓名與權限修改，才能重設密碼或停用帳號。</p><p v-if="lastAdmin" class="cms-field-help">至少需要保留一位使用中的管理員。</p></form></AdminDialog><AdminDialog :open="!!resetting" title="重設第一次登入密碼" @close="!busy&&(resetting=null)"><form class="cms-form" @submit.prevent="save({...resetting,password})"><p>重設後，{{ resetting?.name }} 會立即登出，並需要用新密碼登入及再次更換密碼。</p><label>新密碼<input v-model="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required /></label><p v-if="error" class="cms-error" role="alert">{{ error }}</p><button class="cms-button cms-button-gold" :disabled="busy">確認重設密碼</button></form></AdminDialog></div></template>
